import test from 'node:test';import assert from 'node:assert/strict';
import {compilerLedger,compilerHash} from "../experiments/compiler/model.mjs";
const input='export const value = 12;',stage='const __sa=0; export const value=12;',final='const __sa=0; const value=12; export {value};';
const workspace={'/project/App.tsx':{file:'src/App.tsx',digest:compilerHash(input)}};
function fixture(options={}){const l=compilerLedger(workspace,options),p=l.begin('/project/App.tsx',input);l.stage(p,input,stage);l.finish(p,final);const r={code:final,map:null};l.seal(r,'/project/App.tsx',[p]);const receipt=l.receipt(r,final,'http://127.0.0.1:4173/App.tsx');return{l,p,r,receipt};}
const compiled=(digest=compilerHash(final),extra={})=>({scriptId:'7',url:'http://127.0.0.1:4173/App.tsx',sourceDigest:digest,match:true,contextUniqueId:'context-one',frameId:'frame-one',...extra});
const bind=(f,s=compiled())=>f.l.bind(f.receipt,s,{mainFrameId:'frame-one'});
test('actual workspace stage and exact sealed result bind bytes without claiming execution or ancestry',()=>{const f=fixture(),b=bind(f);assert.equal(b.status,'Code-linked');assert.equal(b.input.file,'src/App.tsx');assert.equal(b.input.digest,compilerHash(input));assert.equal(b.stageDigest,compilerHash(stage));assert.equal(b.finalDigest,compilerHash(final));assert.equal(b.receiptDigest,compilerHash(final));assert.equal(b.fullPath,false);assert.equal(b.invocation,'Unknown/Unsupported');assert.equal(b.readonlyEffects,'Unknown/Unsupported');assert.equal(b.sourceEquivalence,'Unknown/Unsupported');assert.equal(b.completeCompilerInputs,false);assert(!JSON.stringify(f.l.report()).includes(input));});
test('equal result bytes cannot borrow actual object identity and cached same object keeps original pipeline',()=>{const f=fixture();assert.equal(f.l.receipt({code:final,map:null},final,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported');const next=f.l.receipt(f.r,final,'http://127.0.0.1:4173/App.tsx');assert.equal(next.pipelineId,f.receipt.pipelineId);assert.equal(f.l.bind(next,compiled(),{mainFrameId:'frame-one'}).status,'Code-linked');});
test('missing competing wrong-module or failed native stage never supplies a certificate',()=>{for(const mode of ['missing','competing','wrong-module','failed']){const l=compilerLedger(workspace),p=l.begin('/project/App.tsx',input);if(mode!=='missing'){l.stage(p,input,stage);if(mode==='competing')l.stage(p,input,stage);}l.finish(p,final);if(mode==='failed')l.fail(p);const r={code:final};l.seal(r,mode==='wrong-module'?'/project/Other.tsx':'/project/App.tsx',[p]);assert.equal(l.receipt(r,final,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported',mode);}});
test('loader or earlier plugin input changes cannot inherit unchanged workspace digest',()=>{for(const where of ['loader','stage']){const l=compilerLedger(workspace),p=l.begin('/project/App.tsx',where==='loader'?input+'\n// changed':input);l.stage(p,where==='stage'?input+'\n// changed':input,stage);l.finish(p,final);const r={code:final};l.seal(r,'/project/App.tsx',[p]);assert.equal(l.receipt(r,final,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported',where);}});
test('native final result cannot claim a differently transformed output',()=>{const f=fixture();const r={code:final+';void 0'};f.l.seal(r,'/project/App.tsx',[f.p]);assert.equal(f.l.receipt(r,r.code,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported');});
test('single canonical inert sourcemap footer is preserved in exact compiled digest',()=>{const f=fixture(),body=final+'\n//# sourceMappingURL=data:application/json;base64,'+Buffer.from(JSON.stringify({version:3,sources:['App.tsx'],mappings:'AAAA'})).toString('base64');const receipt=f.l.receipt(f.r,body,'http://127.0.0.1:4173/App.tsx');assert.equal(receipt.status,'Observed');const b=f.l.bind(receipt,compiled(compilerHash(body)),{mainFrameId:'frame-one'});assert.equal(b.status,'Code-linked');assert.equal(b.wireEnvelope,'Exact final code plus one inert inline-sourcemap comment');assert.equal(f.l.bind(receipt,compiled(),{mainFrameId:'frame-one'}).status,'Unknown/Unsupported');});
test('normalization extra comments executable tails altered prefixes and corrupt maps refuse',()=>{const f=fixture();for(const body of [final+'\n// extra',final+'\n//# sourceMappingURL=data:application/json;base64,e30=\nvoid 0;',final.replace('12','13'),final+'\n//# sourceMappingURL=data:application/json;base64,notbase64!',final+'\n//# sourceMappingURL=data:application/json;base64,e30='])assert.equal(f.l.receipt(f.r,body,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported');});
test('same URL is insufficient and wrong anonymous sourceURL or context stays unsupported',()=>{const f=fixture();for(const extra of [{sourceDigest:compilerHash('different')},{url:''},{hasSourceURL:true},{contextUniqueId:null},{frameId:'another'},{match:false},{url:'http://127.0.0.1:4173/Other.tsx'}])assert.equal(bind(f,compiled(undefined,extra)).status,'Unknown/Unsupported');});
test('receipt metadata clones and arbitrary objects are not acquired receipt capabilities',()=>{const f=fixture();assert.equal(f.l.bind({...f.receipt},compiled(),{mainFrameId:'frame-one'}).status,'Unknown/Unsupported');assert.equal(f.l.bind({...f.receipt,fullPath:true},compiled(),{mainFrameId:'frame-one'}).fullPath,false);});
test('invalidation rejects old cached results and old receipts without rewriting history',()=>{const f=fixture();f.l.invalidate();assert.equal(bind(f).status,'Stale');assert.equal(f.l.receipt(f.r,final,'http://127.0.0.1:4173/App.tsx').status,'Stale');assert.equal(f.receipt.status,'Observed');});
test('budget loss is sticky and records stay bounded',()=>{const f=fixture({maxPipelines:1,maxReceipts:2});f.l.begin('/project/App.tsx',input);assert.equal(bind(f).status,'Unknown/Unsupported');const g=fixture({maxBytes:4});assert.equal(bind(g).status,'Unknown/Unsupported');assert(g.l.report().gaps.includes('Source/processing byte budget'));});
test('unknown workspace dependencies cannot be certified from names or metadata',()=>{const l=compilerLedger(workspace);assert.equal(l.begin('/project/node_modules/react.js',input),null);const r={code:final};l.seal(r,'/project/node_modules/react.js',[]);assert.equal(l.receipt(r,final,'http://127.0.0.1:4173/node_modules/react.js').status,'Unknown/Unsupported');});

test('mutating a previously sealed native result cannot reuse its old input certificate',()=>{const f=fixture();f.r.code=final+';void 0;';assert.equal(f.l.receipt(f.r,f.r.code,'http://127.0.0.1:4173/App.tsx').status,'Unknown/Unsupported');});
test('editing a returned receipt cannot substitute different compiled bytes',()=>{const f=fixture(),other=compilerHash('other');f.receipt.receiptDigest=other;assert.equal(bind(f,compiled(other)).status,'Unknown/Unsupported');});
test('result accessors and inherited descriptor value getters are not invoked by inspection',()=>{let calls=0;const l=compilerLedger(workspace),r={get code(){calls++;return final;}};Object.defineProperty(Object.prototype,'value',{get(){calls++;return final;},configurable:true});try{l.seal(r,'/project/App.tsx',[]);assert.equal(calls,0);}finally{delete Object.prototype.value;}});

test('returned binding input cannot mutate the private receipt claim',()=>{const f=fixture(),b=bind(f);b.input.digest='forged';assert.equal(bind(f).input.digest,compilerHash(input));});
test('all seven one-byte hashes count against the processing budget',()=>{for(const maxBytes of [7,6]){const l=compilerLedger({'/x':{file:'x',digest:compilerHash('x')}},{maxBytes}),p=l.begin('/x','x');l.stage(p,'x','x');l.finish(p,'x');const r={code:'x'};l.seal(r,'/x',[p]);const receipt=l.receipt(r,'x','/x');assert.equal(receipt.status,maxBytes===7?'Observed':'Unknown/Unsupported');assert.equal(l.report().counts.processedBytes,maxBytes);}});
